ALTER TABLE "web_push_subscriptions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "web_push_subscriptions_owner" ON "web_push_subscriptions" FOR ALL TO "kurrier" USING ("user_id" = nullif(current_setting('request.jwt.claim.sub', true), '')::uuid) WITH CHECK ("user_id" = nullif(current_setting('request.jwt.claim.sub', true), '')::uuid);--> statement-breakpoint
CREATE TABLE "web_push_deliveries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "message_id" uuid REFERENCES "messages"("id") ON DELETE SET NULL, "subscription_id" uuid REFERENCES "web_push_subscriptions"("id") ON DELETE SET NULL, "status" text DEFAULT 'queued' NOT NULL, "attempts" integer DEFAULT 0 NOT NULL, "last_error" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);--> statement-breakpoint
